/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { AccelerateScreen } from "../../src/accelerate/AccelerateScreen.js";
import { CollisionsScreen } from "../../src/collisions/CollisionsScreen.js";
import { EnergyMomentumScreen } from "../../src/energy-momentum/EnergyMomentumScreen.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import { RelativisticDynamicsPreferencesModel } from "../../src/preferences/RelativisticDynamicsPreferencesModel.js";
import RelativisticDynamicsColors from "../../src/RelativisticDynamicsColors.js";
import { ThresholdsScreen } from "../../src/thresholds/ThresholdsScreen.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  // Simulation-specific preferences; initial values come from relativisticDynamicsQueryParameters.
  const simPreferences = new RelativisticDynamicsPreferencesModel(Tandem.ROOT.createTandem("preferences"));

  const screens = [
    new AccelerateScreen(simPreferences, {
      name: stringManager.getScreenNames().accelerateStringProperty,
      tandem: Tandem.ROOT.createTandem("accelerateScreen"),
      backgroundColorProperty: RelativisticDynamicsColors.backgroundColorProperty,
    }),
    new EnergyMomentumScreen(simPreferences, {
      name: stringManager.getScreenNames().energyMomentumStringProperty,
      tandem: Tandem.ROOT.createTandem("energyMomentumScreen"),
      backgroundColorProperty: RelativisticDynamicsColors.backgroundColorProperty,
    }),
    new CollisionsScreen({
      name: stringManager.getScreenNames().collisionsStringProperty,
      tandem: Tandem.ROOT.createTandem("collisionsScreen"),
      backgroundColorProperty: RelativisticDynamicsColors.backgroundColorProperty,
    }),
    new ThresholdsScreen({
      name: stringManager.getScreenNames().thresholdsStringProperty,
      tandem: Tandem.ROOT.createTandem("thresholdsScreen"),
      backgroundColorProperty: RelativisticDynamicsColors.backgroundColorProperty,
    }),
  ];

  return { screens, tracked: { RelativisticDynamicsColors, stringManager, simPreferences } };
}

let built: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    built = buildSim();
    return built.screens;
  },
  tracked: () => built?.tracked ?? {},
});
